        if not isinstance(state, dict):
            state = {}
        state.update({"schema": 1, "device_id": self._xunlei_runtime_device_id, "updated_at": self._now_text(), **values})
        # 这里只保存诊断和稳定 device；captcha_token 本身不写进公开状态数据。
