xunlei_integrity_v1116:
"""迅雷秒传完整性校验与空占位清理。

真实运行发现 get_res_center_token 会先创建 upload task；当后续
check_can_flash_upload 未真正命中时，任务/占位文件可能仍短暂出现在目标目录。
旧实现又只凭 get_info_by_task_id 返回 fileId 就判定秒传成功，没有校验 fileSize，
因此 0B/尺寸异常占位存在被误判为成功的风险。

本层坚持“迅雷只做秒传，不做 OSS/本地下载”：
- get_res_center_token code=156 仍视为秒传命中信号，但必须再确认目标目录出现同名且大小一致的文件；
- check_can_flash_upload 只有真实 40-hex CID 才进入探测；无真实 CID 时不做无意义 check；
- canFlashUpload=true 或真实 CID check 返回可轮询 taskId 时，最终仍必须校验 fileId + 文件大小；
- 失败时删除 upload task，并只清理由本次请求新产生的同名 0B/尺寸异常占位，不碰原有文件；
- 同一批次相同 gcid/size/cid 只探测一次，避免不同分享重复制造 upload task。
"""

from __future__ import annotations

import time
from typing import Any, Dict, List, Tuple

from .xunlei_flash_v193 import _HEX32_RE, _HEX40_RE, _safe_int


class GuangYaXunleiIntegrityV1116Mixin:
    """在 ViewingDispatch 与旧 XunleiFlash 之间收紧秒传成功合同。"""

    build_id = "20260902-r28"

    # ------------------------------------------------------------------
    # 光鸭目录完整性检查
    # ------------------------------------------------------------------
    def _xunlei_parent_rows_v1116(self, parent_id: str) -> List[Dict[str, Any]]:
        client, _ = self._get_guangya_runtime()
        if not client:
            return []
        getter = getattr(client, "get_file_list", None)
        rows: List[Dict[str, Any]] = []
        if callable(getter):
            for page in range(3):
                try:
                    body = getter(
                        parent_id=str(parent_id or ""),
                        page_size=100,
                        order_by=3,
                        sort_type=1,
                        file_types=[],
                        page=page,
                    )
                except TypeError:
                    try:
                        body = getter(parent_id=str(parent_id or ""), page_size=100, page=page)
                    except Exception:
                        break
                except Exception:
                    break
                data = body.get("data") if isinstance(body, dict) else None
                listing = data.get("list") if isinstance(data, dict) else None
                page_rows = [dict(row) for row in (listing or []) if isinstance(row, dict)]
                rows.extend(page_rows)
                total = _safe_int(data.get("total") if isinstance(data, dict) else 0, 0)
                if not page_rows or len(page_rows) < 100 or (total and len(rows) >= total):
                    break
            return rows

        # 兼容少数旧版 GuangYaClient 没有公开 get_file_list 的运行态。
        try:
            body = self._guangya_userres_request(
                "/userres/v1/file/get_file_list",
                {
                    "parentId": str(parent_id or ""),
                    "page": 0,
                    "pageSize": 100,
                    "orderBy": 3,
                    "sortType": 1,
                    "fileTypes": [],
                },
            )
            data = body.get("data") if isinstance(body, dict) else None
            return [dict(row) for row in ((data or {}).get("list") or []) if isinstance(row, dict)]
        except Exception:
            return []

    @staticmethod
    def _xunlei_remote_meta_v1116(row: Dict[str, Any]) -> Tuple[str, str, int, bool]:
        file_id = str(row.get("fileId") or row.get("fileid") or row.get("file_id") or "").strip()
        name = str(row.get("fileName") or row.get("name") or row.get("file_name") or "").strip()
        size = _safe_int(row.get("fileSize") or row.get("size") or row.get("file_size"), 0)
        is_dir = row.get("resType") == 2 or str(row.get("kind") or "").lower() in {"dir", "folder", "drive#folder"}
        return file_id, name, size, is_dir

    def _xunlei_snapshot_v1116(self, parent_id: str, name: str) -> Dict[str, int]:
        snapshot: Dict[str, int] = {}
        for row in self._xunlei_parent_rows_v1116(parent_id):
            file_id, row_name, row_size, is_dir = self._xunlei_remote_meta_v1116(row)
            if is_dir or not file_id or row_name != name:
                continue
            snapshot[file_id] = row_size
        return snapshot

    def _xunlei_find_exact_file_v1116(
        self,
        parent_id: str,
        name: str,
        expected_size: int,
    ) -> Dict[str, Any]:
        for row in self._xunlei_parent_rows_v1116(parent_id):
            file_id, row_name, row_size, is_dir = self._xunlei_remote_meta_v1116(row)
            if is_dir or not file_id or row_name != name:
                continue
            if row_size == int(expected_size or 0) and row_size > 0:
                return {
                    "file_id": file_id,
                    "name": row_name,
                    "size": row_size,
                    "row": row,
                }
        return {}

    def _xunlei_wait_exact_file_v1116(
        self,
        parent_id: str,
        name: str,
        expected_size: int,
        *,
        attempts: int = 10,
    ) -> Dict[str, Any]:
        for index in range(max(1, int(attempts or 1))):
            found = self._xunlei_find_exact_file_v1116(parent_id, name, expected_size)
            if found:
                return found
            if index + 1 < attempts:
                time.sleep(0.2 if index < 4 else 0.35)
        return {}

    def _xunlei_delete_upload_task_v1116(self, task_id: str) -> bool:
        task_id = str(task_id or "").strip()
        if not task_id:
            return True
        try:
            body = self._guangya_userres_request(
                "/userres/v1/file/delete_upload_task",
                {"taskIds": [task_id]},
            )
            code = body.get("code") if isinstance(body, dict) else None
            msg = str(body.get("msg") or body.get("message") or "") if isinstance(body, dict) else ""
            ok = code in (None, 0, "0", 200, "200") or msg.lower() in {"success", "ok"}
            if not ok:
                self._plugin_log(
                    "WARNING",
                    "【光鸭转存助手】【迅雷秒传】upload task 清理未确认：task=%s code=%s msg=%s",
                    task_id[:80],
                    code,
                    msg[:180] or "-",
                )
            return bool(ok)
        except Exception as err:
            self._plugin_log(
                "WARNING",
                "【光鸭转存助手】【迅雷秒传】upload task 清理异常：task=%s error=%s",
                task_id[:80],
                str(err)[:220],
            )
            return False

    def _xunlei_cleanup_placeholders_v1116(
        self,
        parent_id: str,
        name: str,
        expected_size: int,
        before: Dict[str, int],
        *,
        task_id: str = "",
    ) -> Dict[str, Any]:
        self._xunlei_delete_upload_task_v1116(task_id)

        # 删除前再看一次：如果任务其实已经落成完整文件，就绝不清理，并把它当成功。
        exact = self._xunlei_find_exact_file_v1116(parent_id, name, expected_size)
        if exact:
            return exact

        victims: List[str] = []
        for row in self._xunlei_parent_rows_v1116(parent_id):
            file_id, row_name, row_size, is_dir = self._xunlei_remote_meta_v1116(row)
            if is_dir or not file_id or row_name != name or file_id in before:
                continue
            # 只碰本轮新出现且尺寸错误的同名文件，避免误删历史正常内容。
            if row_size <= 0 or row_size != int(expected_size or 0):
                victims.append(file_id)
        if not victims:
            return {}

        client, _ = self._get_guangya_runtime()
        delete_file = getattr(client, "delete_file", None) if client else None
        try:
            if callable(delete_file):
                response = delete_file(victims)
            else:
                response = self._guangya_userres_request(
                    "/userres/v1/file/delete_file",
                    {"fileIds": victims},
                )
            self._plugin_log(
                "WARNING",
                "【光鸭转存助手】【迅雷秒传】已清理本轮新生成的空/尺寸异常占位：name=%s count=%s expected=%s response=%s",
                name[:180],
                len(victims),
                int(expected_size or 0),
                str((response or {}).get("msg") or (response or {}).get("code") or "submitted")[:120] if isinstance(response, dict) else "submitted",
            )
        except Exception as err:
            self._plugin_log(
                "WARNING",
                "【光鸭转存助手】【迅雷秒传】占位文件清理失败：name=%s count=%s error=%s",
                name[:180],
                len(victims),
                str(err)[:220],
            )
        return {}

    # ------------------------------------------------------------------
    # task 最终完成必须验证大小，fileId 本身不再代表成功
    # ------------------------------------------------------------------
    def _xunlei_poll_task_integrity_v1116(
        self,
        task_id: str,
        parent_id: str,
        name: str,
        expected_size: int,
    ) -> Dict[str, Any]:
        for index in range(30):
            body = self._guangya_userres_request(
                "/userres/v1/file/get_info_by_task_id",
                {"taskId": str(task_id)},
            )
            data = body.get("data") if isinstance(body, dict) else None
            if isinstance(data, dict):
                file_id = str(data.get("fileId") or data.get("fileid") or data.get("file_id") or "").strip()
                observed_size = _safe_int(data.get("fileSize") or data.get("size") or data.get("file_size"), 0)
                if file_id and observed_size == int(expected_size or 0) and observed_size > 0:
                    return {
                        "file_id": file_id,
                        "size": observed_size,
                        "task_data": data,
                    }
                if file_id:
                    found = self._xunlei_find_exact_file_v1116(parent_id, name, expected_size)
                    if found:
                        return found
            elif index % 5 == 4:
                found = self._xunlei_find_exact_file_v1116(parent_id, name, expected_size)
                if found:
                    return found
            time.sleep(0.25 if index < 4 else 0.45)

        return self._xunlei_find_exact_file_v1116(parent_id, name, expected_size)

    # ------------------------------------------------------------------
    # 严格秒传：没有完整文件就绝不返回 success=True
    # ------------------------------------------------------------------
    def _rapid_transfer_xunlei_file(self, subscribe: Any, row: Dict[str, Any]) -> Dict[str, Any]:
        gcid = str(row.get("gcid") or "").strip().upper()
        size = _safe_int(row.get("size"), 0)
        if not _HEX40_RE.match(gcid) or size <= 0:
            return {"success": False, "reason": "缺少有效 GCID 或文件大小"}

        md5 = str(row.get("md5") or "").strip().lower()
        if not _HEX32_RE.match(md5):
            # 与用户已验证脚本保持兼容：只作为 get_res_center_token 索引兜底，
            # 不把这 32 位值伪装成 CID 发送给 check_can_flash_upload。
            md5 = gcid.lower()[:32]

        cid_candidates: List[str] = []
        raw_cid = str(row.get("cid") or "").strip().lower()
        if _HEX40_RE.match(raw_cid) and raw_cid != gcid.lower():
            cid_candidates.append(raw_cid)
        if row.get("download_url"):
            triple = self._xunlei_compute_triple_cid(str(row.get("download_url") or ""), size)
            if _HEX40_RE.match(triple) and triple.lower() != gcid.lower() and triple.lower() not in cid_candidates:
                cid_candidates.append(triple.lower())

        _, parent_id = self._xunlei_target_parent(
            subscribe,
            str(row.get("path") or row.get("name") or ""),
        )
        name = str(
            row.get("name")
            or str(row.get("path") or "").rsplit("/", 1)[-1]
            or "file"
        ).strip()
        before = self._xunlei_snapshot_v1116(parent_id, name)

        # 同一预检批次内，相同内容 + 相同真实 CID 不重复创建 upload task。
        dedupe_key = f"{gcid}:{size}:{cid_candidates[0] if cid_candidates else '-'}"
        seen = getattr(self, "_xunlei_flash_integrity_seen_v1116", None)
        if isinstance(seen, set):
            if dedupe_key in seen:
                return {
                    "success": False,
                    "reason": "同批次相同 GCID/size/CID 已探测，跳过重复秒传请求",
                    "duplicate": True,
                }
            seen.add(dedupe_key)

        token_candidates: List[Dict[str, Any]] = []
        for cid in cid_candidates:
            token_candidates.extend([
                {"gcid": gcid.lower(), "cid": cid.lower(), "md5": md5.lower(), "fileSize": size},
                {"gcid": gcid.upper(), "cid": cid.upper(), "md5": md5.upper(), "fileSize": size},
                {"gcid": gcid.lower(), "cid": cid.lower(), "fileSize": size},
            ])
        token_candidates.extend([
            {"gcid": gcid.lower(), "md5": md5.lower(), "fileSize": size},
            {"gcid": gcid.lower(), "fileSize": size},
            {"md5": md5.lower(), "fileSize": size},
        ])

        task_id = ""
        used_res: Dict[str, Any] = {}
        last_error = ""
        for res in token_candidates:
            try:
                body = self._guangya_userres_request(
                    "/userres/v1/get_res_center_token",
                    {
                        "capacity": 2,
                        "res": res,
                        "name": name,
                        "parentId": parent_id,
                    },
                )
            except Exception as err:
                last_error = str(err)[:240]
                continue
            code = body.get("code") if isinstance(body, dict) else None
            if code in (156, "156"):
                exact = self._xunlei_wait_exact_file_v1116(
                    parent_id,
                    name,
                    size,
                    attempts=12,
                )
                if exact:
                    return {
                        "success": True,
                        "instant": True,
                        "file_id": exact.get("file_id"),
                        "verified_size": exact.get("size"),
                        "reason": "get_res_center_token code=156，且目标文件大小校验通过",
                    }
                # 156 本应瞬时完成；看不到完整文件时不能凭业务码宣称成功。
                self._xunlei_cleanup_placeholders_v1116(
                    parent_id,
                    name,
                    size,
                    before,
                )
                return {
                    "success": False,
                    "reason": "get_res_center_token 返回 156，但目标目录未确认到同名同大小文件；已拒绝空壳成功",
                }

            candidate_task = self._guangya_task_id(body)
            if candidate_task:
                task_id = candidate_task
                used_res = dict(res)
                break
            last_error = str(
                body.get("msg")
                or body.get("message")
                or body.get("error")
                or code
                or "秒传令牌未命中"
            )[:240]

        if not task_id:
            return {"success": False, "reason": last_error or "光鸭未创建秒传任务"}

        # 没有真实 CID 时，check_can_flash_upload 没有可靠命中条件；插件又明确禁止 OSS/普通上传，
        # 因此立即清理任务并回退，不制造空轮询/空占位。
        if not cid_candidates:
            recovered = self._xunlei_cleanup_placeholders_v1116(
                parent_id,
                name,
                size,
                before,
                task_id=task_id,
            )
            if recovered:
                return {
                    "success": True,
                    "instant": True,
                    "task_id": task_id,
                    "file_id": recovered.get("file_id"),
                    "verified_size": recovered.get("size"),
                    "reason": "任务清理前已确认目标文件完整，按完整性结果记为成功",
                }
            return {
                "success": False,
                "task_id": task_id,
                "reason": "缺少真实 CID；仅保留秒传模式，已清理 upload task 并回退下一来源",
            }

        accepted_task = ""
        check_message = ""
        for cid in cid_candidates:
            checks = [
                {"taskId": task_id, "gcid": gcid.lower(), "cid": cid.lower(), "fileSize": size},
                {"taskId": task_id, "gcid": gcid.upper(), "cid": cid.upper(), "fileSize": size},
                {"taskId": task_id, "gcid": gcid.lower(), "cid": cid.lower(), "md5": md5.lower(), "fileSize": size},
            ]
            for check in checks:
                try:
                    body = self._guangya_userres_request(
                        "/userres/v1/check_can_flash_upload",
                        check,
                    )
                except Exception as err:
                    check_message = str(err)[:220]
                    continue
                data = body.get("data") if isinstance(body, dict) else None
                if isinstance(data, dict) and data.get("canFlashUpload") is True:
                    accepted_task = str(data.get("taskId") or task_id)
                    break

                # 有真实 CID 的情况下，服务端可能只给“处理中 taskId”；允许轮询，
                # 但绝不再把 taskId/fileId 本身当成功，最终仍由文件大小验真。
                candidate_task = self._guangya_task_id(body)
                code = body.get("code") if isinstance(body, dict) else None
                if candidate_task and code in (None, 0, "0", 147, "147"):
                    accepted_task = candidate_task
                    break
                check_message = str(
                    body.get("msg")
                    or body.get("message")
                    or body.get("error")
                    or code
                    or "未命中"
                )[:220]
            if accepted_task:
                break

        if accepted_task:
            verified = self._xunlei_poll_task_integrity_v1116(
                accepted_task,
                parent_id,
                name,
                size,
            )
            if verified:
                return {
                    "success": True,
                    "instant": True,
                    "task_id": accepted_task,
                    "file_id": verified.get("file_id"),
                    "verified_size": verified.get("size"),
                    "reason": "光鸭秒传完成，fileId 与文件大小校验通过",
                }

        recovered = self._xunlei_cleanup_placeholders_v1116(
            parent_id,
            name,
            size,
            before,
            task_id=accepted_task or task_id,
        )
        if recovered:
            return {
                "success": True,
                "instant": True,
                "task_id": accepted_task or task_id,
                "file_id": recovered.get("file_id"),
                "verified_size": recovered.get("size"),
                "reason": "轮询未确认但目标目录已出现同名同大小完整文件，按完整性结果记为成功",
            }

        return {
            "success": False,
            "task_id": accepted_task or task_id,
            "reason": f"光鸭秒传未命中或完整性校验失败；upload task/新空占位已清理，回退下一来源{('：' + check_message) if check_message else ''}",
        }

    def _dispatch_xunlei_flash(self, subscribe: Any) -> Dict[str, Any]:
        previous = getattr(self, "_xunlei_flash_integrity_seen_v1116", None)
        self._xunlei_flash_integrity_seen_v1116 = set()
        try:
            return super()._dispatch_xunlei_flash(subscribe)
        finally:
            self._xunlei_flash_integrity_seen_v1116 = previous


__all__ = ["GuangYaXunleiIntegrityV1116Mixin"]

xunlei_json_pipeline_v1117:
"""按用户已验证秒传脚本复刻“迅雷生成 JSON -> 光鸭导入 JSON”两阶段协议。

不要再把迅雷分享读取和光鸭秒传接口拼成一条自创流程。稳定脚本的真实边界是：
1. 迅雷侧把分享文件导出成标准 JSON（sourceTag=xunlei，顶层/行级同时保留
   shareId/passCodeToken，并保留 gcid/md5/cid/tripleCid/wholeCid/downloadUrl）；
2. 光鸭侧 importMd5Json 解析该 JSON，再按既定候选顺序探测 get_res_center_token /
   check_can_flash_upload。

MoviePilot 版本唯一主动裁掉的是 capacity=1/OSS 普通上传兜底：迅雷在插件里只作为
“秒传来源”，秒传不命中必须回退光鸭分享/Magnet/ED2K，不能把大文件下载到 MP。
"""

from __future__ import annotations

import json
import time
from typing import Any, Dict, Iterable, List, Optional, Tuple

import requests

from .xunlei_flash_v193 import _HEX32_RE, _HEX40_RE, _pick_download_url, _safe_int


class GuangYaXunleiJsonPipelineV1117Mixin:
    """复刻稳定脚本的 Xunlei JSON 生产/消费合同。"""

    build_id = "20260902-r30"

    # ------------------------------------------------------------------
    # Stage A: 迅雷分享 -> 标准 JSON 模板
    # ------------------------------------------------------------------
    def _xunlei_share_files(self, share_id: str, pass_code_token: str) -> List[Dict[str, Any]]:
        rows = list(super()._xunlei_share_files(share_id, pass_code_token) or [])
        for row in rows:
            if not isinstance(row, dict):
                continue
            row["shareId"] = str(share_id or "")
            row["passCodeToken"] = str(pass_code_token or "")
            row["sourceTag"] = "xunlei"
            row["sourceXunlei"] = True
            if row.get("id") and not row.get("fileId"):
                row["fileId"] = str(row.get("id") or "")
        return rows

    def _xunlei_post_json_v1117(self, endpoint: str, body: Dict[str, Any], *, action: str) -> Dict[str, Any]:
        """分享下载链接 POST 路径；保持匿名分享头，不携带用户 Bearer。"""
        url = f"https://api-pan.xunlei.com{endpoint}"
        last_error = ""
        for attempt in range(2):
            headers = dict(self._xunlei_headers(action, refresh=False) or {})
            if not headers.get("x-captcha-token"):
                raise RuntimeError("迅雷 captcha_token 不可用")
            session = self._xunlei_session()
            try:
                response = session.post(
                    url,
                    json=dict(body or {}),
                    headers=headers,
                    timeout=int(getattr(self, "_provider_timeout", 15) or 15),
                )
                try:
                    payload = response.json()
                except Exception:
                    payload = {}
                if response.status_code < 400:
                    return payload if isinstance(payload, dict) else {}
                last_error = str(
                    (payload or {}).get("error_description")
                    or (payload or {}).get("error")
                    or (payload or {}).get("message")
                    or response.text
                    or f"HTTP {response.status_code}"
                )[:300]
                captcha_error = False
                try:
                    captcha_error = bool(self._xunlei_captcha_error(response, payload))
                except Exception:
                    captcha_error = response.status_code in (400, 401, 403) and "captcha" in last_error.lower()
                if attempt == 0 and captcha_error:
                    self._xunlei_runtime_captcha_token = ""
                    refreshed = str(self._refresh_xunlei_captcha(action) or "")
                    if refreshed:
                        continue
                break
            except requests.RequestException as err:
                last_error = str(err)[:300]
                break
        raise RuntimeError(f"迅雷分享下载链接接口失败：{last_error or 'unknown error'}")

    def _xunlei_file_info(self, share_id: str, pass_code_token: str, row: Dict[str, Any]) -> Dict[str, Any]:
        """等价稳定脚本 getFileDetail/_fetchFileHash 的服务端精简版。"""
        merged = dict(row or {})
        merged["shareId"] = str(share_id or "")
        merged["passCodeToken"] = str(pass_code_token or "")
        merged["sourceTag"] = "xunlei"
        merged["sourceXunlei"] = True
        if merged.get("id") and not merged.get("fileId"):
            merged["fileId"] = str(merged.get("id") or "")

        # 快速通道：与脚本 _fetchFileHash 一致，优先 share/file_info。
        try:
            first = dict(super()._xunlei_file_info(share_id, pass_code_token, merged) or merged)
            for key, value in first.items():
                if value not in (None, "", [], {}):
                    merged[key] = value
        except Exception:
            pass

        file_id = str(merged.get("id") or merged.get("fileId") or "").strip()
        parent_id = str(merged.get("parent_id") or merged.get("parentId") or "").strip()

        # 如果 file_info 没给真实下载地址，按脚本继续查当前 parent 的 share/detail。
        if file_id and not str(merged.get("download_url") or merged.get("downloadUrl") or "").strip():
            for with_audit in ("true", "false"):
                try:
                    detail = self._xunlei_get(
                        "/drive/v1/share/detail",
                        {
                            "share_id": share_id,
                            "parent_id": parent_id,
                            "pass_code_token": pass_code_token,
                            "limit": 200,
                            "with_audit": with_audit,
                            "thumbnail_size": "SIZE_LARGE",
                            "usage": "CONSUME",
                        },
                        action="get:/drive/v1/share/detail",
                    )
                    candidates = detail.get("files") or (detail.get("data") or {}).get("files") or []
                    hit = next(
                        (item for item in candidates if isinstance(item, dict) and str(item.get("id") or item.get("file_id") or "") == file_id),
                        None,
                    )
                    if isinstance(hit, dict):
                        normalized = self._xunlei_normalize_file(
                            hit,
                            str(merged.get("path") or "").rsplit("/", 1)[0],
                            parent_id,
                        )
                        for key in ("gcid", "md5", "cid", "download_url", "size"):
                            if normalized.get(key):
                                merged[key] = normalized[key]
                        if merged.get("download_url"):
                            break
                except Exception:
                    continue

        # 与稳定脚本 Path 3 一致：GET/detail 仍没 downloadUrl 时尝试 POST 下载链接端点。
        if file_id and not str(merged.get("download_url") or merged.get("downloadUrl") or "").strip():
            post_candidates: List[Tuple[str, Dict[str, Any]]] = [
                ("/drive/v1/share/download", {"share_id": share_id, "file_ids": [file_id], "pass_code_token": pass_code_token}),
                (f"/drive/v1/share/{share_id}/download", {"file_ids": [file_id], "pass_code_token": pass_code_token}),
                ("/drive/v1/share/files/download", {"share_id": share_id, "file_id": file_id, "pass_code_token": pass_code_token}),
                ("/drive/v1/share/file/download", {"share_id": share_id, "file_id": file_id, "pass_code_token": pass_code_token}),
            ]
            for endpoint, payload in post_candidates:
                try:
                    body = self._xunlei_post_json_v1117(endpoint, payload, action=f"post:{endpoint}")
                    dl = str(_pick_download_url(body) or "").strip().strip("`\"'")
                    if dl.lower().startswith(("http://", "https://")):
                        merged["download_url"] = dl
                        break
                except Exception:
                    continue

        # 稳定脚本路径 4：files/{id} 同时尝试分享 query。该端点在部分账号/区域
        # 才会返回 web_content_link，因此只作为兜底，且仍透传分享上下文。
        if file_id and not str(merged.get("download_url") or merged.get("downloadUrl") or "").strip():
            try:
                detail = self._xunlei_get(
                    f"/drive/v1/files/{file_id}",
                    {
                        "space": "",
                        "usage": "CONSUME",
                        "share_id": share_id,
                        "pass_code_token": pass_code_token,
                    },
                    action=f"get:/drive/v1/files/{file_id}",
                )
                normalized = self._xunlei_normalize_file(
                    dict(detail or {}),
                    str(merged.get("path") or "").rsplit("/", 1)[0],
                    parent_id,
                )
                for key in ("gcid", "md5", "cid", "download_url", "size"):
                    if normalized.get(key):
                        merged[key] = normalized[key]
            except Exception:
                pass

        # 稳定脚本路径 5：最后才尝试 share/save。响应可能直接带文件信息，
        # 也可能只给 task_id；后一种必须先回查任务，再读取新文件详情。
        if file_id and share_id and pass_code_token and not str(
            merged.get("download_url") or merged.get("downloadUrl") or ""
        ).strip():
            try:
                saved = self._xunlei_post_json_v1117(
                    "/drive/v1/share/save",
                    {
                        "share_id": share_id,
                        "file_ids": [file_id],
                        "pass_code_token": pass_code_token,
                    },
                    action="post:/drive/v1/share/save",
                )
                saved_data = saved.get("data") if isinstance(saved.get("data"), dict) else saved
                saved_hit = saved_data.get("file") if isinstance(saved_data, dict) and isinstance(saved_data.get("file"), dict) else saved_data
                task_id = str(
                    (saved_data or {}).get("task_id")
                    or (saved_data or {}).get("taskId")
                    or saved.get("task_id")
                    or saved.get("taskId")
                    or ""
                ).strip()
                if task_id:
                    for index in range(20):
                        try:
                            task = self._xunlei_get(
                                f"/drive/v1/tasks/{task_id}",
                                {},
                                action=f"get:/drive/v1/tasks/{task_id}",
                            )
                            task_data = task.get("data") if isinstance(task.get("data"), dict) else task
                            candidate = (
                                task_data.get("file")
                                or task_data.get("file_info")
                                or task_data.get("files")
                                or task_data.get("result")
                            ) if isinstance(task_data, dict) else None
                            if isinstance(candidate, list):
                                candidate = candidate[0] if candidate else None
                            if isinstance(candidate, dict):
                                saved_hit = candidate
                                break
                        except Exception:
                            pass
                        time.sleep(0.2 if index < 4 else 0.4)
                if isinstance(saved_hit, dict):
                    normalized = self._xunlei_normalize_file(
                        saved_hit,
                        str(merged.get("path") or "").rsplit("/", 1)[0],
                        parent_id,
                    )
                    for key in ("gcid", "md5", "cid", "download_url", "size"):
                        if normalized.get(key):
                            merged[key] = normalized[key]
            except Exception:
                pass

        # JSON 模板字段名与用户脚本对齐。
        if merged.get("download_url") and not merged.get("downloadUrl"):
            merged["downloadUrl"] = str(merged.get("download_url") or "")
        if merged.get("cid") and not merged.get("tripleCid"):
            cid = str(merged.get("cid") or "").strip()
            gcid = str(merged.get("gcid") or "").strip()
            if _HEX40_RE.fullmatch(cid) and cid.lower() != gcid.lower():
                merged["tripleCid"] = cid.lower()
        return merged

    @staticmethod
    def _xunlei_format_size_v1117(size: int) -> str:
        value = float(max(0, int(size or 0)))
        units = ("B", "KB", "MB", "GB", "TB")
        for unit in units:
            if value < 1024 or unit == units[-1]:
                return f"{value:.2f} {unit}" if unit != "B" else f"{int(value)} B"
            value /= 1024.0
        return f"{int(size or 0)} B"

    def _xunlei_make_json_v1117(self, rows: Iterable[Dict[str, Any]]) -> Dict[str, Any]:
        """等价 helper.makeJson(..., 'xunlei', {shareId, passCodeToken})。"""
        normalized: List[Dict[str, Any]] = []
        top_share = ""
        top_pass = ""
        for raw in rows:
            row = dict(raw or {})
            path = str(row.get("path") or row.get("name") or "").replace("\\", "/").strip()
            if not path:
                continue
            size = _safe_int(row.get("size") or row.get("fileSize"), 0)
            gcid = str(row.get("gcid") or "").strip().lower()
            md5 = str(row.get("md5") or "").strip().lower()
            # v1.1.3 脚本在迅雷极速 JSON 中使用 gcid 前 32 位作为 md5 兜底；
            # 用户实测 cid/downloadUrl 为空时，光鸭仍可据此全部瞬时命中。
            if not _HEX32_RE.fullmatch(md5) and _HEX40_RE.fullmatch(gcid):
                md5 = gcid[:32]
            file_id = str(row.get("fileId") or row.get("id") or "").strip()
            cid = str(row.get("cid") or "").strip()
            triple = str(row.get("tripleCid") or "").strip()
            whole = str(row.get("wholeCid") or "").strip()
            parent_id = str(row.get("parentId") or row.get("parent_id") or "").strip()
            download_url = str(row.get("downloadUrl") or row.get("download_url") or "").strip().strip("`\"'")
            share_id = str(row.get("shareId") or "").strip()
            pass_token = str(row.get("passCodeToken") or "").strip()
            top_share = top_share or share_id
            top_pass = top_pass or pass_token
            # 与 v1.1.3 makeJson 完全一致：行级只写 sourceXunlei，sourceTag 仅写顶层。
            entry: Dict[str, Any] = {"size": str(size), "path": path, "cid": cid, "parentId": parent_id, "downloadUrl": download_url, "sourceXunlei": True}
            if _HEX40_RE.fullmatch(gcid):
                entry["gcid"] = gcid
            if _HEX32_RE.fullmatch(md5):
                entry["md5"] = md5
            if file_id:
                entry["fileId"] = file_id
            if _HEX40_RE.fullmatch(triple):
                entry["tripleCid"] = triple
            if _HEX40_RE.fullmatch(whole):
                entry["wholeCid"] = whole
            if share_id:
                entry["shareId"] = share_id
            if pass_token:
                entry["passCodeToken"] = pass_token
            normalized.append(entry)

        total_size = sum(_safe_int(row.get("size"), 0) for row in normalized)
        result: Dict[str, Any] = {
            "scriptVersion": "1.1.3",
            "scriptAuthor": "sumuve",
            "totalFilesCount": len(normalized),
            "totalSize": total_size,
            "formattedTotalSize": self._xunlei_format_size_v1117(total_size),
            "files": normalized,
            "sourceTag": "xunlei",
        }
        if top_share:
            result["shareId"] = top_share
        if top_pass:
            result["passCodeToken"] = top_pass
        return result

    # ------------------------------------------------------------------
    # Stage B: 标准 JSON -> 光鸭 importMd5Json 的纯秒传子集
    # ------------------------------------------------------------------
    @staticmethod
    def _xunlei_unique_payloads_v1117(rows: Iterable[Dict[str, Any]]) -> List[Dict[str, Any]]:
        result: List[Dict[str, Any]] = []
        seen = set()
        for row in rows:
            key = json.dumps(row, sort_keys=True, ensure_ascii=False, separators=(",", ":"))
            if key in seen:
                continue
            seen.add(key)
            result.append(row)
        return result

    def _xunlei_import_json_file_v1117(
        self,
        subscribe: Any,
        obj: Dict[str, Any],
        source_row: Dict[str, Any],
    ) -> Dict[str, Any]:
        files = obj.get("files") if isinstance(obj, dict) else None
        if not isinstance(files, list) or not files:
            return {"success": False, "reason": "内部迅雷 JSON 中无 files 数组"}
        f = dict(files[0] or {})

        top_share = str(obj.get("shareId") or "").strip()
        top_pass = str(obj.get("passCodeToken") or "").strip()
        share_id = str(f.get("shareId") or top_share).strip()
        pass_token = str(f.get("passCodeToken") or top_pass).strip()
        gcid = str(f.get("gcid") or "").strip().upper()
        size = _safe_int(f.get("size"), 0)
        if not _HEX40_RE.fullmatch(gcid) or size <= 0:
            return {"success": False, "reason": "内部迅雷 JSON 缺少有效 GCID/size"}

        lower_gcid = gcid.lower()
        md5 = str(f.get("md5") or "").strip().lower()
        if not _HEX32_RE.fullmatch(md5):
            md5 = lower_gcid[:32]
        upper_md5 = md5.upper()

        cid_values: List[str] = []
        for raw in (f.get("cid"), f.get("tripleCid"), f.get("wholeCid")):
            value = str(raw or "").strip()
            if _HEX40_RE.fullmatch(value) and value.lower() != lower_gcid:
                if value.lower() not in cid_values:
                    cid_values.append(value.lower())
                if value.upper() not in cid_values:
                    cid_values.append(value.upper())

        download_url = str(f.get("downloadUrl") or "").strip().strip("`\"'")
        # 与 importMd5Json 一致：迅雷 JSON 有真实 downloadUrl 时，现场计算标准 3x20KB cid。
        if download_url.lower().startswith(("http://", "https://")):
            triple = str(self._xunlei_compute_triple_cid(download_url, size) or "").strip()
            if _HEX40_RE.fullmatch(triple) and triple.lower() != lower_gcid:
                for value in (triple.lower(), triple.upper()):
                    if value not in cid_values:
                        cid_values.insert(0, value)

        relative_path = str(f.get("path") or source_row.get("path") or source_row.get("name") or "file")
        _, parent_id = self._xunlei_target_parent(subscribe, relative_path)
        name = relative_path.replace("\\", "/").rsplit("/", 1)[-1] or "file"
        snapshot_fn = getattr(self, "_xunlei_snapshot_v1116", None)
        before = snapshot_fn(parent_id, name) if callable(snapshot_fn) else {}

        # importMd5Json 的 capacity=2 候选顺序。capacity=1 是普通上传，插件明确禁用。
        res_combos: List[Dict[str, Any]] = []
        for cid in cid_values:
            res_combos.append({"capacity": 2, "res": {"gcid": lower_gcid, "cid": cid, "fileSize": size}})
            if gcid != lower_gcid:
                res_combos.append({"capacity": 2, "res": {"gcid": gcid, "cid": cid, "fileSize": size}})

        md5_combos: List[Dict[str, Any]] = []
        if md5:
            for cid in cid_values:
                md5_combos.append({"capacity": 2, "res": {"gcid": lower_gcid, "cid": cid, "md5": md5, "fileSize": size}})
                if upper_md5 != md5:
                    md5_combos.append({"capacity": 2, "res": {"gcid": lower_gcid, "cid": cid, "md5": upper_md5, "fileSize": size}})
            md5_combos.append({"capacity": 2, "res": {"gcid": lower_gcid, "md5": md5, "fileSize": size}})
            if upper_md5 != md5:
                md5_combos.append({"capacity": 2, "res": {"gcid": lower_gcid, "md5": upper_md5, "fileSize": size}})
            md5_combos.append({"capacity": 2, "res": {"md5": md5, "fileSize": size}})

        token_candidates = self._xunlei_unique_payloads_v1117([
            *res_combos,
            *md5_combos,
            {"capacity": 2, "res": {"gcid": lower_gcid, "fileSize": size}},
            {"capacity": 2, "res": {"md5": lower_gcid[:32], "fileSize": size}},
        ])

        task_id = ""
        last_error = ""
        for candidate in token_candidates:
            try:
                body = self._guangya_userres_request(
                    "/userres/v1/get_res_center_token",
                    {
                        **candidate,
                        "name": name,
                        "parentId": str(parent_id or ""),
                    },
                )
            except Exception as err:
                last_error = str(err)[:240]
                continue
            code = body.get("code") if isinstance(body, dict) else None
            if code in (156, "156"):
                # 用户脚本把 156 作为已经确认的瞬时秒传命中。
                verify = getattr(self, "_xunlei_wait_exact_file_v1116", None)
                exact = verify(parent_id, name, size, attempts=8) if callable(verify) else {}
                return {
                    "success": True,
                    "instant": True,
                    "file_id": str((exact or {}).get("file_id") or ""),
                    "verified_size": _safe_int((exact or {}).get("size"), 0),
                    "json_stage": True,
                    "reason": "内部 JSON 导入：get_res_center_token code=156",
                }
            candidate_task = str(self._guangya_task_id(body) or "")
            if candidate_task:
                task_id = candidate_task
                break
            last_error = str(
                body.get("msg")
                or body.get("message")
                or body.get("error")
                or code
                or "秒传令牌未命中"
            )[:240]

        if not task_id:
            return {"success": False, "reason": last_error or "内部 JSON 导入未取得 upload task", "json_stage": True}

        # importMd5Json 的 check 候选：真实 cid 优先，其后 md5-only；没有任何两者才纯 gcid。
        checks: List[Dict[str, Any]] = []
        for cid in cid_values:
            checks.append({"taskId": task_id, "gcid": lower_gcid, "cid": cid, "fileSize": size})
            if gcid != lower_gcid:
                checks.append({"taskId": task_id, "gcid": gcid, "cid": cid, "fileSize": size})
            if md5:
                checks.append({"taskId": task_id, "gcid": lower_gcid, "cid": cid, "md5": md5, "fileSize": size})
                if upper_md5 != md5:
                    checks.append({"taskId": task_id, "gcid": lower_gcid, "cid": cid, "md5": upper_md5, "fileSize": size})
        if md5:
            checks.append({"taskId": task_id, "gcid": lower_gcid, "md5": md5, "fileSize": size})
            if upper_md5 != md5:
                checks.append({"taskId": task_id, "gcid": lower_gcid, "md5": upper_md5, "fileSize": size})
        if not checks:
            checks.append({"taskId": task_id, "gcid": lower_gcid, "fileSize": size})
        checks = self._xunlei_unique_payloads_v1117(checks)

        last_check: Dict[str, Any] = {}
        for check in checks:
            try:
                body = self._guangya_userres_request("/userres/v1/check_can_flash_upload", check)
            except Exception as err:
                last_error = str(err)[:240]
                continue
            last_check = dict(body or {})
            data = body.get("data") if isinstance(body, dict) else None
            if isinstance(data, dict) and data.get("canFlashUpload") is True:
                break

        check_data = last_check.get("data") if isinstance(last_check, dict) else None
        can_flash = isinstance(check_data, dict) and check_data.get("canFlashUpload") is True
        check_task = str((check_data or {}).get("taskId") or task_id) if isinstance(check_data, dict) else task_id
        had_real_cid = bool(cid_values)

        # 与稳定脚本一致：无 canFlashUpload 但返回 taskId，仅当确实有真实 cid 参与时才轮询。
        # 稳定脚本在这里还可走 OSS；MoviePilot 按既定策略禁用 OSS，所以无真实 cid 直接清 task 回退。
        if not can_flash and not had_real_cid:
            cleanup = getattr(self, "_xunlei_cleanup_placeholders_v1116", None)
            if callable(cleanup):
                cleanup(parent_id, name, size, before, task_id=check_task or task_id)
            else:
                try:
                    self._guangya_userres_request("/userres/v1/file/delete_upload_task", {"taskIds": [check_task or task_id]})
                except Exception:
                    pass
            return {
                "success": False,
                "task_id": check_task or task_id,
                "json_stage": True,
                "reason": "内部 JSON 导入未取得真实 CID/canFlashUpload；按纯秒传策略清理 task 并回退",
            }

        poll = getattr(self, "_xunlei_poll_task_integrity_v1116", None)
        verified = poll(check_task or task_id, parent_id, name, size) if callable(poll) else {}
        if verified:
            return {
                "success": True,
                "instant": True,
                "task_id": check_task or task_id,
                "file_id": str(verified.get("file_id") or ""),
                "verified_size": _safe_int(verified.get("size"), 0),
                "json_stage": True,
                "reason": "内部 JSON 导入：光鸭秒传完成，文件大小校验通过",
            }

        cleanup = getattr(self, "_xunlei_cleanup_placeholders_v1116", None)
        if callable(cleanup):
            recovered = cleanup(parent_id, name, size, before, task_id=check_task or task_id)
            if recovered:
                return {
                    "success": True,
                    "instant": True,
                    "task_id": check_task or task_id,
                    "file_id": str(recovered.get("file_id") or ""),
                    "verified_size": _safe_int(recovered.get("size"), 0),
                    "json_stage": True,
                    "reason": "内部 JSON 导入：轮询结束前目标文件已完整落盘",
                }
        else:
            try:
                self._guangya_userres_request("/userres/v1/file/delete_upload_task", {"taskIds": [check_task or task_id]})
            except Exception:
                pass
        return {
            "success": False,
            "task_id": check_task or task_id,
            "json_stage": True,
            "reason": "内部 JSON 导入秒传未命中；已清理任务/异常占位，回退下一来源",
        }

    def _rapid_transfer_xunlei_file(self, subscribe: Any, row: Dict[str, Any]) -> Dict[str, Any]:
        # 先按脚本生成整份分享 JSON；导入阶段再取当前文件，避免 planner 裁剪模板。
        full_template = row.get("_xunlei_json_template") if isinstance(row, dict) else None
        if not isinstance(full_template, dict):
            full_template = self._xunlei_make_json_v1117([row])
        full_files = full_template.get("files") or []
        batch_index = _safe_int(row.get("_xunlei_json_index"), 0)
        if batch_index < 0 or batch_index >= len(full_files):
            return {"success": False, "reason": "迅雷 JSON 批次索引无效"}
        template = dict(full_template)
        template["files"] = [dict(full_files[batch_index] or {})]
        files = template.get("files") or []
        if not files:
            return {"success": False, "reason": "迅雷 JSON 模板生成失败"}
        preview = dict(files[0] or {})
        self._plugin_log(
            "INFO",
            "【光鸭转存助手】【迅雷JSON】整批模板已生成：total=%s current=%s path=%s size=%s gcid=%s md5=%s cid=%s dl=%s share=%s；下一步按光鸭 importMd5Json 合同导入",
            len(full_files), batch_index + 1,
            str(preview.get("path") or "")[:180],
            _safe_int(preview.get("size"), 0),
            "yes" if preview.get("gcid") else "no",
            "yes" if preview.get("md5") else "no",
            "yes" if (preview.get("cid") or preview.get("tripleCid") or preview.get("wholeCid")) else "no",
            "yes" if preview.get("downloadUrl") else "no",
            "yes" if (preview.get("shareId") or template.get("shareId")) else "no",
        )
        return self._xunlei_import_json_file_v1117(subscribe, template, dict(row or {}))

    def _xunlei_import_json_batch_v1123(
        self,
        subscribe: Any,
        template: Dict[str, Any],
        source_rows: Iterable[Dict[str, Any]],
        skip_indexes: Optional[Iterable[int]] = None,
        include_indexes: Optional[Iterable[int]] = None,
    ) -> Dict[str, Any]:
        """接收完整脚本模板，但只按允许索引执行光鸭导入合同。"""
        files = list(template.get("files") or []) if isinstance(template, dict) else []
        rows = [dict(row or {}) for row in source_rows]
        skipped = {int(value) for value in (skip_indexes or [])}
        included = {int(value) for value in include_indexes} if include_indexes is not None else set(range(len(files)))
        if not files or len(files) != len(rows):
            return {"success": False, "results": [], "message": "迅雷完整 JSON 与来源文件数量不一致"}
        self._plugin_log(
            "INFO",
            "【光鸭转存助手】【迅雷JSON】批次导入开始：selected=%s source_total=%s share=%s；完整 JSON 已生成，仅按真实缺集索引导入",
            len(included),
            len(files),
            str(template.get("shareId") or "-")[:30],
        )
        results: List[Dict[str, Any]] = []
        for index, (entry, source_row) in enumerate(zip(files, rows)):
            if index not in included:
                continue
            self._plugin_log(
                "INFO",
                "【光鸭转存助手】【迅雷JSON】批次文件导入：current=%s/%s path=%s gcid=%s md5=%s cid=%s dl=%s",
                index + 1, len(files), str(entry.get("path") or "")[:180],
                "yes" if entry.get("gcid") else "no", "yes" if entry.get("md5") else "no",
                "yes" if (entry.get("cid") or entry.get("tripleCid") or entry.get("wholeCid")) else "no",
                "yes" if entry.get("downloadUrl") else "no",
            )
            if index in skipped:
                result = {"success": True, "skipped": True, "reason": "此前已确认完成"}
            else:
                single = dict(template)
                single["files"] = [dict(entry or {})]
                result = dict(self._xunlei_import_json_file_v1117(subscribe, single, source_row) or {})
            self._plugin_log(
                "INFO" if result.get("success") else "WARNING",
                "【光鸭转存助手】【迅雷JSON】批次文件结果：current=%s/%s success=%s path=%s reason=%s",
                index + 1, len(files), bool(result.get("success")),
                str(entry.get("path") or "")[:180], str(result.get("reason") or "-")[:280],
            )
            results.append({"index": index, "file": dict(entry or {}), "result": result})
        success_count = sum(1 for item in results if bool((item.get("result") or {}).get("success")))
        self._plugin_log(
            "INFO" if success_count else "WARNING",
            "【光鸭转存助手】【迅雷JSON】批次导入结束：total=%s success=%s failed=%s",
            len(results), success_count, len(results) - success_count,
        )
        return {
            "success": success_count > 0,
            "total": len(results),
            "successful": success_count,
            "results": results,
            "message": f"迅雷 JSON 批次导入完成：成功 {success_count}/{len(results)}",
        }


__all__ = ["GuangYaXunleiJsonPipelineV1117Mixin"]

xunlei_reliability_v1100:
"""v1.10.0 迅雷秒传运行可靠性层。

重点修复 Range 服务器忽略 Range 时 requests 先把整部大文件读进内存的风险：
所有 CID 样本均使用 stream=True，单段最多读取 20KiB；非零 Range 若返回 200 立即放弃，
绝不通过跳读整文件来计算 CID。另增加非破坏性的秒传预检 API，分别报告观影、迅雷身份和
光鸭运行时是否就绪。

v1.12.5 追加跨关键词重试边界：一次迅雷秒传调用内部即使会降级多个 GYING 关键词，
只要底层迅雷分享 API 已打开 captcha 熔断，就把该熔断视为整个召回轮次的终止事实，
不能因为下一档关键词重新进入 RuntimeFix 并重置 captcha circuit 后再次访问迅雷分享接口。
同时把外部检索治理放在召回扩大之前：频道事件、外部冷却或自动搜索关闭时，RecallGuard
不能利用旧搜索缓存直接发起宽关键词 GYING 请求。
"""

from __future__ import annotations

import hashlib
import re
from typing import Any, Dict, List

import requests

from .provider_sources_v192 import _proxy_dict


_CONTENT_RANGE_RE = re.compile(r"bytes\s+(\d+)-(\d+)/(?:\d+|\*)", re.I)


class GuangYaXunleiReliabilityV1100Mixin:
    """最终 CID 采样边界、秒传预检、外部检索治理与跨关键词 captcha 熔断保持。"""

    build_id = "20260901-r11"
    _CID_SAMPLE_SIZE = 20 * 1024

    @staticmethod
    def _read_limited_stream(response: requests.Response, limit: int) -> bytes:
        """只消费 limit 字节，达到上限立即停止；调用方负责 close。"""
        limit = max(0, int(limit or 0))
        if limit <= 0:
            return b""
        data = bytearray()
        for chunk in response.iter_content(chunk_size=min(8192, limit)):
            if not chunk:
                continue
            remaining = limit - len(data)
            if remaining <= 0:
                break
            data.extend(chunk[:remaining])
            if len(data) >= limit:
                break
        return bytes(data)

    def _merge_xunlei_rounds_v1125(self, base: Dict[str, Any], extra: Dict[str, Any]) -> Dict[str, Any]:
        """让一次秒传调用里的 captcha 熔断跨关键词保持，避免宽搜重新打迅雷分享 API。"""
        merged = dict(super()._merge_xunlei_rounds_v1125(base, extra) or {})
        captcha_open = bool((base or {}).get("captcha_circuit_open")) or bool(
            (extra or {}).get("captcha_circuit_open")
        )
        if not captcha_open:
            return merged

        merged["captcha_circuit_open"] = True
        # RecallGuard 的关键词循环在 merge 后会检查同一个 thread-local stop 标记。
        # 这里不伪造 handled=True：captcha 失败只终止迅雷继续扩大搜索，后续 Magnet/ED2K
        # 仍应按既有来源优先级继续执行。
        local_getter = getattr(self, "_recall_retry_local_v1125", None)
        if callable(local_getter):
            try:
                local_getter().stop_after_failure = True
            except Exception:
                pass
        return merged

    def _dispatch_viewing_external_v1113(self, subscribe: Any) -> Dict[str, Any]:
        """RecallGuard 扩大关键词前再次执行外部治理，禁止频道/冷却路径绕过 GYING 门禁。"""
        sid = int(getattr(subscribe, "id", 0) or 0)
        if not bool(getattr(self, "_provider_auto_search", True)):
            return {
                "success": False,
                "actions": [],
                "message": "观影自动搜索已关闭",
            }
        if not bool(getattr(self, "_external_auto_dispatch", True)):
            return {
                "success": False,
                "actions": [],
                "message": "Magnet/ED2K 自动云添加已关闭",
            }

        mode_reader = getattr(self, "_route_source_mode_value_v1115", None)
        mode = str(mode_reader() if callable(mode_reader) else getattr(self, "_route_source_mode_v1115", "") or "")
        if mode == "channel_event":
            return {
                "success": False,
                "actions": [],
                "cooldown": True,
                "channel_only": True,
                "message": "频道事件只消费已到达资源，本轮禁止主动 GYING",
            }

        round_ok = getattr(self, "_external_round_ok_v1114", None)
        if callable(round_ok) and not bool(round_ok(subscribe)):
            return {
                "success": False,
                "actions": [],
                "cooldown": True,
                "subscribe_id": sid,
                "message": "外部观影检索处于冷却/本轮未授权状态，不扩大 GYING 关键词",
            }
        return dict(super()._dispatch_viewing_external_v1113(subscribe) or {})

    def _xunlei_compute_triple_cid(self, download_url: str, file_size: int) -> str:
        download_url = str(download_url or "").strip()
        try:
            file_size = int(file_size or 0)
        except (TypeError, ValueError):
            file_size = 0
        if not download_url or file_size <= 0:
            return ""

        sample_size = self._CID_SAMPLE_SIZE
        if file_size <= sample_size:
            ranges = [(0, file_size - 1)] * 3
        else:
            ranges = [
                (0, min(sample_size - 1, file_size - 1)),
                (file_size // 3, min(file_size // 3 + sample_size - 1, file_size - 1)),
                (max(0, file_size - sample_size), file_size - 1),
            ]

        session = requests.Session()
        proxies = _proxy_dict(bool(getattr(self, "_provider_proxy", False)))
        if proxies:
            session.proxies.update(proxies)
        timeout = int(getattr(self, "_provider_timeout", 15) or 15)
        chunks: List[bytes] = []

        for start, end in ranges:
            expected = end - start + 1
            response: requests.Response | None = None
            try:
                response = session.get(
                    download_url,
                    headers={
                        "Range": f"bytes={start}-{end}",
                        "Referer": "https://pan.xunlei.com/",
                        "Origin": "https://pan.xunlei.com",
                        "Accept-Encoding": "identity",
                    },
                    timeout=timeout,
                    stream=True,
                    allow_redirects=True,
                )
                if response.status_code == 206:
                    content_range = str(response.headers.get("Content-Range") or "")
                    matched = _CONTENT_RANGE_RE.search(content_range)
                    if matched and (int(matched.group(1)) != start or int(matched.group(2)) != end):
                        return ""
                    content = self._read_limited_stream(response, expected)
                    if len(content) != expected:
                        return ""
                    chunks.append(content)
                    continue

                if response.status_code == 200:
                    # Range 被忽略时只能安全取得文件开头；中段/尾段若继续读取就会为了
                    # 20KiB 样本跳过数 GB 数据，违反秒传“绝不整文件中转”的边界。
                    if start != 0:
                        return ""
                    content = self._read_limited_stream(response, expected)
                    if len(content) != expected:
                        return ""
                    chunks.append(content)
                    continue
                return ""
            except Exception:
                return ""
            finally:
                if response is not None:
                    try:
                        response.close()
                    except Exception:
                        pass
        return hashlib.sha1(b"".join(chunks)).hexdigest()

    def _xunlei_rapid_readiness(self) -> Dict[str, Any]:
        stages: List[Dict[str, Any]] = []

        try:
            client, api = self._get_guangya_runtime()
            request = getattr(client, "_request", None) if client else None
            guangya_ok = bool(client and api and callable(request))
            stages.append({
                "key": "guangya",
                "name": "光鸭运行时",
                "ok": guangya_ok,
                "message": "已取得登录客户端与存储 API" if guangya_ok else "光鸭云盘助手未运行、未登录或缺少 userres 请求能力",
            })
        except Exception as err:
            guangya_ok = False
            stages.append({"key": "guangya", "name": "光鸭运行时", "ok": False, "message": str(err)[:240]})

        try:
            headers = self._xunlei_headers("get:/drive/v1/share")
            captcha_ok = bool(headers.get("x-captcha-token"))
            device_ok = bool(headers.get("x-device-id"))
            client_ok = bool(headers.get("x-client-id"))
            xunlei_ok = captcha_ok and device_ok and client_ok
            stages.append({
                "key": "xunlei_identity",
                "name": "迅雷匿名分享身份",
                "ok": xunlei_ok,
                "message": (
                    "captcha / device / client 已就绪"
                    if xunlei_ok
                    else "迅雷 captcha、device 或 client 尚未就绪"
                ),
                "captcha_ready": captcha_ok,
                "device_ready": device_ok,
                "client_ready": client_ok,
            })
        except Exception as err:
            xunlei_ok = False
            stages.append({"key": "xunlei_identity", "name": "迅雷匿名分享身份", "ok": False, "message": str(err)[:240]})

        if bool(getattr(self, "_viewing_enabled", False)):
            try:
                _, login = self._viewing_session()
                viewing_ok = bool(login.get("success"))
                stages.append({
                    "key": "viewing",
                    "name": "观影会话",
                    "ok": viewing_ok,
                    "message": str(login.get("message") or ("已就绪" if viewing_ok else "不可用"))[:240],
                    "node": str(login.get("node") or ""),
                    "login_mode": str(login.get("mode") or ""),
                })
            except Exception as err:
                viewing_ok = False
                stages.append({"key": "viewing", "name": "观影会话", "ok": False, "message": str(err)[:240]})
        else:
            viewing_ok = False
            stages.append({"key": "viewing", "name": "观影会话", "ok": False, "message": "观影未启用"})

        ready = bool(guangya_ok and xunlei_ok and viewing_ok and getattr(self, "_xunlei_flash_enabled", True))
        return {
            "success": ready,
            "rapid_ready": ready,
            "flash_enabled": bool(getattr(self, "_xunlei_flash_enabled", True)),
            "stages": stages,
            "message": "迅雷秒传链路预检通过" if ready else "迅雷秒传链路尚未完全就绪，请查看 stages",
            "updated_at": self._now_text(),
        }

    def api_xunlei_preflight(self) -> Dict[str, Any]:
        result = self._xunlei_rapid_readiness()
        self.save_data("xunlei_preflight_last", result)
        return result

    def api_xunlei_flash_test(self, share_url: str = "", passcode: str = "") -> Dict[str, Any]:
        """分享读取测试 + 秒传运行时就绪度；不创建光鸭文件/上传任务。"""
        share_result = dict(super().api_xunlei_flash_test(share_url=share_url, passcode=passcode) or {})
        readiness = self._xunlei_rapid_readiness()
        share_ok = bool(share_result.get("success"))
        combined = {
            **share_result,
            "success": bool(share_ok and readiness.get("rapid_ready")),
            "share_read_success": share_ok,
            "rapid_ready": bool(readiness.get("rapid_ready")),
            "preflight": readiness,
        }
        if share_ok and not readiness.get("rapid_ready"):
            combined["message"] = f"迅雷分享可读，但秒传运行时未就绪：{readiness.get('message')}"
        self.save_data("xunlei_flash_test_last", {
            "success": combined.get("success"),
            "share_read_success": combined.get("share_read_success"),
            "rapid_ready": combined.get("rapid_ready"),
            "message": str(combined.get("message") or "")[:300],
            "updated_at": self._now_text(),
        })
        return combined

    def get_api(self):
        apis = list(super().get_api() or [])
        paths = {str(item.get("path") or "") for item in apis if isinstance(item, dict)}
        if "/xunlei/flash/preflight" not in paths:
            apis.append({
                "path": "/xunlei/flash/preflight",
                "endpoint": self.api_xunlei_preflight,
                "methods": ["POST"],
                "summary": "非破坏性检测观影/迅雷/光鸭秒传链路",
            })
        return apis


